    def fetch_markets(self, params={}) -> list[Market]:
        """
        retrieves data on all markets for wallex

        https://developers.wallex.ir

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict[]: an array of objects representing market data
        """
        response = self.publicGetV1Markets(params)
        #
        #     {
        #         "result": { "symbols": { "BTCUSDT": { ... }, "USDTTMN": { ... } } },
        #         "message": "The operation was successful",
        #         "success": true
        #     }
        #
        result = self.safe_dict(response, 'result', {})
        symbols = self.safe_dict(result, 'symbols', {})
        markets = list(symbols.values())
        return self.parse_markets(markets)

    def parse_market(self, market: dict) -> Market:
        #
        #     {
        #         "symbol": "USDTTMN",
        #         "baseAsset": "USDT",
        #         "baseAssetPrecision": 8,
        #         "quoteAsset": "TMN",
        #         "quotePrecision": 0,
        #         "stepSize": 2,        // amount decimals, not a step
        #         "tickSize": 0,        // price decimals, not a tick
        #         "minQty": 0.01,
        #         "minNotional": 50000,
        #         "stats": { ... },
        #         "createdAt": "2020-12-01T00:00:00Z",
        #         ...
        #     }
        #
        id = self.safe_string(market, 'symbol')
        baseId = self.safe_string(market, 'baseAsset')
        quoteId = self.safe_string(market, 'quoteAsset')
        base = self.safe_currency_code(baseId)
        quote = self.safe_currency_code(quoteId)
        return self.safe_market_structure({
            'id': id,
            'symbol': base + '/' + quote,
            'base': base,
            'quote': quote,
            'baseId': baseId,
            'quoteId': quoteId,
            'type': 'spot',
            'spot': True,
            'margin': False,
            'swap': False,
            'future': False,
            'option': False,
            'active': True,
            'contract': False,
            'precision': {
                'amount': self.parse_number(self.parse_precision(self.safe_string(market, 'stepSize'))),
                'price': self.parse_number(self.parse_precision(self.safe_string(market, 'tickSize'))),
            },
            'limits': {
                'amount': {'min': self.safe_number(market, 'minQty'), 'max': None},
                'price': {'min': None, 'max': None},
                'cost': {'min': self.safe_number(market, 'minNotional'), 'max': None},
                'leverage': {'min': None, 'max': None},
            },
            'created': self.parse8601(self.safe_string(market, 'createdAt')),
            'info': market,
        })

    def fetch_balance(self, params={}) -> Balances:
        """
        query for balance and get the amount of funds available for trading or funds locked in orders

        https://developers.wallex.ir

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a `balance structure <https://docs.ccxt.com/?id=balance-structure>`
        """
        self.load_markets()
        response = self.privateGetV1AccountBalances(params)
        return self.parse_balance(response)

    def parse_balance(self, response: object) -> Balances:
        #
        #     {
        #         "result": {
        #             "balances": {
        #                 "BTC": { "asset": "BTC", "faName": "بیت کوین", "fiat": false, "value": "0.5", "locked": "0.1" },
        #                 "TMN": { "asset": "TMN", "faName": "تومان", "fiat": true, "value": "1000000", "locked": "0" }
        #             }
        #         },
        #         "success": true
        #     }
        #
        result = {'info': response}
        data = self.safe_dict(response, 'result', {})
        balances = self.safe_dict(data, 'balances', {})
        currencyIds = list(balances.keys())
        for i in range(0, len(currencyIds)):
            currencyId = currencyIds[i]
            balance = self.safe_dict(balances, currencyId, {})
            account = self.account()
            account['total'] = self.safe_string(balance, 'value')
            account['used'] = self.safe_string(balance, 'locked')
            code = self.safe_currency_code(currencyId)
            if code is not None:
                result[code] = account
        return self.safe_balance(result)

    def create_order(self, symbol: str, type: OrderType, side: OrderSide, amount: float, price: Num = None, params={}) -> Order:
        """
        create a trade order

        https://developers.wallex.ir/docs/spot-create-order

        :param str symbol: unified symbol of the market to create an order in
        :param str type: 'market' or 'limit'
        :param str side: 'buy' or 'sell'
        :param float amount: how much of the base currency you want to trade
        :param float [price]: the price at which the order is to be fulfilled, wallex marks it required for every type
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param float [params.triggerPrice]: turns the order into STOP_LIMIT or STOP_MARKET
        :param str [params.clientOrderId]: [A-Z0-9_], must be unique
        :returns dict: an `order structure <https://docs.ccxt.com/?id=order-structure>`
        """
        self.load_markets()
        market = self.market(symbol)
        request = {
            'symbol': market['id'],
            'type': type.upper(),
            'side': 'BUY' if (side == 'buy') else 'SELL',
            'quantity': self.amount_to_precision(symbol, amount),
        }
        if price is not None:
            request['price'] = self.price_to_precision(symbol, price)
        triggerPrice = self.safe_string_2(params, 'triggerPrice', 'stopPrice')
        if triggerPrice is not None:
            request['type'] = 'STOP_' + type.upper()
            request['stop_Price'] = self.price_to_precision(symbol, triggerPrice)  # sic, capital P
        clientOrderId = self.safe_string(params, 'clientOrderId')
        if clientOrderId is not None:
            request['client_id'] = clientOrderId
        params = self.omit(params, ['triggerPrice', 'stopPrice', 'clientOrderId'])
        response = self.privatePostV1AccountOrders(self.extend(request, params))
        #
        #     {
        #         "message": "...",
        #         "result": {
        #             "symbol": "BTCUSDT", "type": "LIMIT", "side": "BUY", "clientOrderId": "test_clientId",
        #             "price": "82494", "origQty": "0.001", "executedQty": "0", "executedSum": "0", "executedPrice": "0",
        #             "sum": "82.494", "executedPercent": 0, "status": "NEW", "active": true, "fee": "0", "fills": [],
        #             "stopPrice": null, "transactTime": 1700000000, "created_at": "2023-11-14T22:13:20Z"
        #         },
        #         "success": true
        #     }
        #
        result = self.safe_dict(response, 'result', {})
        return self.parse_order(result, market)

    def parse_order(self, order: dict, market: Market = None) -> Order:
        marketId = self.safe_string(order, 'symbol')
        market = self.safe_market(marketId, market)
        statuses = self.safe_dict(self.options, 'orderStatuses', {})
        status = self.safe_string(order, 'status')
        type = self.safe_string_lower(order, 'type')  # LIMIT, MARKET, STOP_LIMIT, STOP_MARKET
        if type is not None:
            type = type.replace('stop_', '')
        average = self.safe_string(order, 'executedPrice')
        if Precise.string_eq(average, '0'):
            average = None
        # wallex identifies orders by clientOrderId for fetch and cancel
        clientOrderId = self.safe_string(order, 'clientOrderId')
        return self.safe_order({
            'id': clientOrderId,
            'clientOrderId': clientOrderId,
            'timestamp': self.parse8601(self.safe_string(order, 'created_at')),
            'datetime': None,
            'lastTradeTimestamp': None,
            'symbol': market['symbol'],
            'type': type,
            'timeInForce': None,
            'postOnly': None,
            'side': self.safe_string_lower(order, 'side'),
            'price': self.safe_string(order, 'price'),
            'triggerPrice': self.safe_string(order, 'stopPrice'),
            'amount': self.safe_string(order, 'origQty'),
            'filled': self.safe_string(order, 'executedQty'),
            'remaining': None,
            'cost': self.safe_string(order, 'executedSum'),
            'average': average,
            'status': self.safe_string(statuses, status, status),
            'fee': {
                'cost': self.safe_string(order, 'fee'),
                'currency': None,
            },
            'trades': None,
            'info': order,
        }, market)

    def sign(self, path: object, api: object = 'public', method='GET', params={}, headers: dict = None, body: Str = None):
        url = self.urls['api']['rest'] + '/' + self.implode_params(path, params)
        query = self.omit(params, self.extract_params(path))
        headers = {}
        if api == 'private':
            # wallex authenticates with the raw key in x-api-key, there is no secret and no hmac signature
            self.check_required_credentials()
            headers['X-API-KEY'] = self.apiKey
        if method == 'GET':
            if len(query) > 0:
                url += '?' + self.urlencode(query)
        else:
            body = self.json(query)
            headers['Content-Type'] = 'application/json'
        return {'url': url, 'method': method, 'body': body, 'headers': headers}

    def handle_errors(self, httpCode: int, reason: str, url: str, method: str, headers: dict, body: str, response: object, requestHeaders: object, requestBody: object):
        if response is None:
            return None
        #
        #     { "code": 1201, "message": "invalid API key format", "result": {}, "success": false }
        #
        success = self.safe_bool(response, 'success')
        if success is False:
            code = self.safe_string(response, 'code')
            if code == '1201':
                raise AuthenticationError(self.id + ' ' + body)
            raise ExchangeError(self.id + ' ' + body)
        return None
